/**
 * invoice.db.js
 *
 * Invoices table column reference (from 20260101000000_initial_schema.sql):
 *   id, clinic_id, invoice_number, patient_id, appointment_id,
 *   subtotal, discount, tax, total, amount_paid, balance_due,
 *   status, issued_at, due_at, created_at, updated_at,
 *   description (added in migration 20260103)
 *
 * invoice_items: id, invoice_id, description, quantity, unit_price, discount, amount
 *
 * All monetary values are stored in PAISE (integer).
 */
const supabase = require('../config/supabase')

/** Create an invoice header. invoice_number is auto-generated by DB sequence. */
async function create(invoiceData) {
  const { data, error } = await supabase
    .from('invoices')
    .insert([invoiceData])
    .select()
    .single()
  if (error) throw new Error(error.message)
  return data
}

/** Create invoice + line items. Returns { invoice, items }. */
async function createWithItems(invoiceData, items) {
  const invoice = await create(invoiceData)

  if (items && items.length > 0) {
    const itemRows = items.map(item => ({ ...item, invoice_id: invoice.id }))
    const { data: insertedItems, error: itemsError } = await supabase
      .from('invoice_items')
      .insert(itemRows)
      .select()
    if (itemsError) throw new Error(itemsError.message)
    return { invoice, items: insertedItems || [] }
  }

  return { invoice, items: [] }
}

/** Fetch a single invoice by ID with its line items. */
async function findById(id) {
  const { data, error } = await supabase
    .from('invoices')
    .select('*, invoice_items(*), patient:patients(id, name, patient_number, phone)')
    .eq('id', id)
    .single()
  if (error) {
    if (error.code === 'PGRST116') return null
    throw new Error(error.message)
  }
  return data
}

/** Fetch all invoices for a patient, newest first, with line items. */
async function findByPatient(patientId) {
  const { data, error } = await supabase
    .from('invoices')
    .select('*, invoice_items(*)')
    .eq('patient_id', patientId)
    .eq('is_deleted', false)
    .order('created_at', { ascending: false })
  if (error) throw new Error(error.message)
  return data || []
}

/** Update invoice fields. */
async function updateInvoice(id, fields) {
  const { data, error } = await supabase
    .from('invoices')
    .update({ ...fields, updated_at: new Date().toISOString() })
    .eq('id', id)
    .select()
    .single()
  if (error) throw new Error(error.message)
  return data
}

/** Soft-delete an invoice. */
async function softDelete(id) {
  const { data, error } = await supabase
    .from('invoices')
    .update({ is_deleted: true, deleted_at: new Date().toISOString() })
    .eq('id', id)
    .select()
    .single()
  if (error) throw new Error(error.message)
  return data
}

/**
 * Recalculate amount_paid + balance_due + status from live payments.
 * Uses the real column name `total` (not `total_amount`).
 * All values are in PAISE.
 */
async function recalcInvoiceBalance(invoiceId) {
  // Sum all non-deleted payments that reference this invoice
  const { data: pays } = await supabase
    .from('payments')
    .select('amount')
    .eq('invoice_id', invoiceId)
    .eq('is_deleted', false)

  const totalPaidPaise = (pays || []).reduce((sum, p) => sum + (p.amount || 0), 0)

  // Fetch invoice total using real column name `total`
  const { data: inv } = await supabase
    .from('invoices')
    .select('total')
    .eq('id', invoiceId)
    .single()
  if (!inv) return

  const totalPaise   = inv.total || 0
  const balancePaise = Math.max(0, totalPaise - totalPaidPaise)

  let status = 'issued'
  if (totalPaidPaise <= 0)    status = 'issued'
  else if (balancePaise <= 0) status = 'paid'
  else                        status = 'partially_paid'

  await supabase
    .from('invoices')
    .update({
      amount_paid: totalPaidPaise,
      balance_due: balancePaise,
      status,
      updated_at:  new Date().toISOString(),
    })
    .eq('id', invoiceId)
}

module.exports = {
  create,
  createWithItems,
  findById,
  findByPatient,
  updateInvoice,
  softDelete,
  recalcInvoiceBalance,
}
